SELECT toJSONString(groupArray(tuple(hostname,metric,samples,first,last,min_value,max_value))) AS payload FROM (SELECT hostname,metric,count() AS samples,min(event_time) AS first,max(event_time) AS last,min(value) AS min_value,max(value) AS max_value FROM clusterAllReplicas(default,merge('system','^asynchronous_metric_log')) WHERE metric IN ('MemoryResident','CGroupMemoryTotal','CGroupMemoryUsed','TrackedMemory') AND event_date='2026-08-08' AND event_time>=toDateTime('2026-08-08 06:55:56','UTC') AND event_time<toDateTime('2026-08-08 07:55:56','UTC') GROUP BY hostname,metric ORDER BY hostname,metric LIMIT 100) LIMIT 1 SETTINGS max_threads=2,max_execution_time=30,timeout_before_checking_execution_speed=0,max_rows_to_read=100000,skip_unavailable_shards=0;
